"""Load WireGuard configurations generated by NET (NET-11, NET-12).

    python manage.py load_wireguard_profiles --dir wg-configs/ [--dry-run]

Reads every `<username>.conf` in --dir (the output of the infra repo's
scripts/make-wg-configs.py, with people.csv `code` set to the site
username), and stores it as that user's profile, replacing any previous
one. Files whose name matches no user are reported and skipped.

The directory holds private keys: run this on the machine that has it,
then delete the directory. Never commit it anywhere.
"""
import pathlib
import re

from django.contrib.auth import get_user_model
from django.core.files.base import ContentFile
from django.core.management.base import BaseCommand, CommandError

from cyberrange.models import WireGuardProfile
from services.submission_service import teams_for

ADDRESS = re.compile(r"^\s*Address\s*=\s*(\S+)", re.MULTILINE)


class Command(BaseCommand):
    help = "Store generated WireGuard configurations as per-user profiles."

    def add_arguments(self, parser):
        parser.add_argument("--dir", required=True)
        parser.add_argument("--dry-run", action="store_true")

    def handle(self, *args, **opts):
        directory = pathlib.Path(opts["dir"])
        if not directory.is_dir():
            raise CommandError(f"{directory} is not a directory")
        User = get_user_model()
        loaded = skipped = 0
        for path in sorted(directory.glob("*.conf")):
            if path.name == "gateway-peers.conf":
                continue
            user = User.objects.filter(username=path.stem).first()
            if user is None:
                self.stderr.write(f"skip {path.name}: no user '{path.stem}'")
                skipped += 1
                continue
            text = path.read_text(encoding="utf-8")
            match = ADDRESS.search(text)
            if opts["dry_run"]:
                self.stdout.write(f"would load {path.name} for {user.username}")
                loaded += 1
                continue
            profile = WireGuardProfile.objects.filter(user=user).first() or WireGuardProfile(user=user)
            if profile.config:
                profile.config.delete(save=False)  # never leave an old private key behind
            profile.config.save(f"{user.username}.conf", ContentFile(text.encode("utf-8")), save=False)
            profile.address = match.group(1) if match else ""
            profile.team = teams_for(user).first()
            profile.revoked = False
            profile.downloaded_at = None
            profile.save()
            loaded += 1
        self.stdout.write(self.style.SUCCESS(f"loaded {loaded}, skipped {skipped}"))
